package dpt

import (
	"math"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// The KNX master data (knx_master.xml, published by the KNX Association
// for ETS) describes every datapoint subtype: its name, text and the
// fields of its format. masterdata_gen.go holds the subtypes of the
// version pinned in dpt/masterdata.lock, generated by internal/cmd/gendpt
// (make generate); the XML itself is not kept in the repository.
//
// The registry is the hand-written table (table.go) plus, for the main
// types whose format the library knows without further semantics, every
// subtype of the master data that the table does not list
// (registerMasterData). The hand-written entries win: they keep their
// names, descriptions, units and ranges. TestMasterDataCoverage keeps the
// rest in view: a subtype of the master data is registered or listed in
// masterDataNotRegistered with the reason.

// mdKind is the kind of a field of a master data format.
type mdKind uint8

const (
	mdBit mdKind = iota + 1
	mdUnsigned
	mdSigned
	mdFloat
	mdEnum
	mdReserved
	mdString
)

// mdField is a field of a subtype's format, most significant first.
type mdField struct {
	Kind  mdKind
	Width int
	// Name is the field's name, Unit its unit symbol.
	Name, Unit string
	// Cleared and Set name the two values of a bit.
	Cleared, Set string
	// Min and Max bound the value when HasRange is set (MinInclusive and
	// MaxInclusive of an integer, MinValue and MaxValue of a float).
	Min, Max float64
	HasRange bool
	// Coefficient scales the raw value of an integer; 0 when none is given.
	Coefficient float64
	// Encoding is the character set of a string.
	Encoding string
	// Enum lists the values of an enumeration.
	Enum []mdEnumValue
}

// mdEnumValue is a value of an enumeration field.
type mdEnumValue struct {
	Value uint32
	Text  string
}

// mdSubtype is a datapoint subtype of the master data.
type mdSubtype struct {
	ID   ID
	Name string
	Text string
	// Bits is the size of the main type.
	Bits   int
	Fields []mdField
}

// masterDataNotRegistered lists the subtypes of the master data that the
// registry does not have, with the reason. Each needs a codec written by
// hand for its layout; TestMasterDataCoverage fails when a subtype is
// neither registered nor listed here, so a new version of the master data
// cannot add subtypes unnoticed.
var masterDataNotRegistered = map[ID]string{
	{24, 1}:    "variable-length string: the registry has fixed sizes only",
	{28, 1}:    "variable-length string: the registry has fixed sizes only",
	{251, 601}: "HSVW colour: no codec for its layout",
	{252, 601}: "relative HSVW control: no codec for its layout",
	{253, 600}: "relative xyY control: no codec for its layout",
	{254, 601}: "relative HSV control: no codec for its layout",
	{247, 600}: "DALI converter test info: no codec for its layout",
	{248, 600}: "DALI converter information: no codec for its layout",
	{272, 600}: "DALI converter information: no codec for its layout",
	{273, 1}:   "forecast of 2-octet floats: no codec for its layout",
	{273, 2}:   "forecast of 2-octet floats: no codec for its layout",
	{273, 3}:   "forecast of 2-octet floats: no codec for its layout",
	{273, 4}:   "forecast of 2-octet floats: no codec for its layout",
	{273, 5}:   "forecast of 2-octet floats: no codec for its layout",
	{273, 6}:   "forecast of 2-octet floats: no codec for its layout",
	{273, 7}:   "forecast of 2-octet floats: no codec for its layout",
	{285, 1}:   "IPv6 address: no codec for its layout",
	{288, 600}: "brightness and RGBW colour transition: no codec for its layout",
	{288, 601}: "brightness and RGBW colour transition: no codec for its layout",
}

// masterRegistered lists the subtypes that registerMasterData added.
var masterRegistered []ID

// registerMasterData registers the subtypes of the master data that the
// table does not have and whose format masterType knows.
func registerMasterData() {
	for i := range masterSubtypes {
		s := &masterSubtypes[i]
		if _, ok := registry[s.ID]; ok {
			continue
		}
		if t, ok := masterType(s); ok {
			register(t)
			masterRegistered = append(masterRegistered, t.ID)
		}
	}
}

// masterType returns the type of a master data subtype whose main type
// has a format the library knows without further semantics: booleans,
// controls, steps, characters, integers (scaled by a power of ten, or a
// one-octet value mapped to 0..max), floats, strings, enumerations and bit
// sets. The other subtypes need a codec of their own.
func masterType(s *mdSubtype) (*Type, bool) {
	t := &Type{ID: s.ID, Name: s.Name, Description: mdText(s.Text), Bits: s.Bits}
	f := s.Fields
	one := len(f) == 1
	switch s.ID.Main {
	case 1:
		if !one || f[0].Kind != mdBit {
			return nil, false
		}
		t.Kind, t.codec = KindBool, boolCodec
		t.Labels = []string{mdText(f[0].Cleared), mdText(f[0].Set)}
	case 2:
		if len(f) != 2 || f[0].Kind != mdBit || f[1].Kind != mdBit {
			return nil, false
		}
		t.Kind, t.codec = KindControl, controlCodec
	case 3:
		if len(f) != 2 || f[0].Kind != mdBit || f[1].Kind != mdUnsigned || f[1].Width != 3 {
			return nil, false
		}
		t.Kind, t.codec = KindStep, stepCodec
	case 4:
		if !one || f[0].Kind != mdString || f[0].Width != 8 {
			return nil, false
		}
		t.Kind, t.codec = KindChar, charCodec
	case 16:
		if !one || f[0].Kind != mdString || f[0].Width != 112 {
			return nil, false
		}
		t.Kind, t.codec = KindString, stringCodec
	case 5, 6, 7, 8, 12, 13, 29:
		if !one || (f[0].Kind != mdUnsigned && f[0].Kind != mdSigned) || f[0].Width != s.Bits {
			return nil, false
		}
		if !mdInteger(t, &f[0]) {
			return nil, false
		}
	case 9, 14:
		if !one || f[0].Kind != mdFloat || f[0].Width != s.Bits {
			return nil, false
		}
		t.Kind, t.Unit = KindFloat, f[0].Unit
		if s.Bits == 16 {
			t.codec = float16Codec
			t.Min, t.Max, t.HasRange = Float16Min, Float16Max, true
			if f[0].HasRange {
				t.Min, t.Max = math.Max(f[0].Min, Float16Min), math.Min(f[0].Max, Float16Max)
			}
		} else {
			t.codec = float32Codec
			t.Min, t.Max, t.HasRange = f[0].Min, f[0].Max, f[0].HasRange
		}
	case 20, 23:
		if !one || f[0].Kind != mdEnum || f[0].Width != s.Bits {
			return nil, false
		}
		t.Kind, t.codec, t.Enum = KindEnum, enumCodec, mdEnumNames(f[0].Enum)
	case 21, 22, 30:
		for _, x := range f {
			if x.Kind != mdBit && x.Kind != mdReserved {
				return nil, false
			}
		}
		t.Kind, t.codec = KindBits, bitsCodec(s.Bits/8)
	default:
		return nil, false
	}
	return t, true
}

// mdInteger sets the kind, unit, range and codec of a one-field integer
// subtype. A coefficient of a power of ten scales the value (7.003 counts
// in 10 ms); a one-octet value with a coefficient of max/255 is mapped to
// 0..max (5.001: 0..100 %). Other coefficients are not handled.
func mdInteger(t *Type, f *mdField) bool {
	signed := f.Kind == mdSigned
	octets := f.Width / 8
	t.Unit = f.Unit
	scale := 1.0
	switch c := f.Coefficient; {
	case c == 0 || c == 1:
	case !signed && octets == 1 && mdRatio(c) > 0:
		max := mdRatio(c)
		t.Kind, t.codec = KindFloat, ratioCodec(max)
		t.Min, t.Max, t.HasRange = 0, max, true
		return true
	case mdPowerOfTen(c):
		scale = c
	default:
		return false
	}
	t.codec = intCodec(octets, signed, scale)
	switch {
	case scale != 1:
		t.Kind = KindFloat
	case signed:
		t.Kind = KindSigned
	default:
		t.Kind = KindUnsigned
	}
	if scale == 1 && f.HasRange {
		t.Min, t.Max, t.HasRange = f.Min, f.Max, true
	}
	return true
}

// mdRatio returns max when c is max/255 for a whole max (the master data
// gives the coefficient rounded to 7 digits), else 0.
func mdRatio(c float64) float64 {
	max := math.Round(c * 255)
	if max < 1 || math.Abs(max/255-c) > 1e-6 {
		return 0
	}
	return max
}

func mdPowerOfTen(c float64) bool {
	if c <= 0 {
		return false
	}
	e := math.Round(math.Log10(c))
	return e >= -6 && e <= 6 && math.Abs(math.Pow(10, e)-c) < 1e-12*math.Max(1, c)
}

// mdEnumNames returns the names of an enumeration's values. Values the
// master data marks "reserved" are left out, as in the hand-written
// table, so that Encode refuses them; values wider than 8 bits are not
// values of the enumeration codec. A value without a text is named by its
// number; a text that an earlier value already has gets the number added
// ("extract air (4)"), so that every name parses to one value.
func mdEnumNames(values []mdEnumValue) map[uint8]string {
	m := make(map[uint8]string, len(values))
	seen := map[string]bool{}
	for _, v := range values {
		if v.Value > math.MaxUint8 || mdReservedText(v.Text) {
			continue
		}
		name := mdText(v.Text)
		if name == "" {
			name = strconv.FormatUint(uint64(v.Value), 10)
		}
		if seen[strings.ToLower(name)] {
			name += " (" + strconv.FormatUint(uint64(v.Value), 10) + ")"
		}
		seen[strings.ToLower(name)] = true
		m[uint8(v.Value)] = name
	}
	return m
}

// mdText returns a text of the master data in the library's style: a
// leading capital that starts a word in lower case is lowered ("Off" is
// "off"); abbreviations ("DALI", "OR") and other text are kept.
func mdText(s string) string {
	s = strings.Join(strings.Fields(s), " ")
	r, n := utf8.DecodeRuneInString(s)
	if n == 0 || !unicode.IsUpper(r) {
		return s
	}
	next, _ := utf8.DecodeRuneInString(s[n:])
	if unicode.IsLower(next) {
		return string(unicode.ToLower(r)) + s[n:]
	}
	return s
}

// mdReservedText reports whether an enumeration value is marked reserved.
func mdReservedText(s string) bool {
	return strings.EqualFold(strings.TrimSpace(s), "reserved")
}
